"targets": [
  { "refId": "A", "datasource": { "type": "prometheus", "uid": "prometheus" }, "instant": true, "range": false, "format": "table",
    "expr": "max by (run, likely_cause, first_check, confidence, generated_at)(last_over_time(work_ai_hint{job=\"day25-work-view\"}[$__range])) * on(run) group_left(impact) max by (run, impact)(last_over_time(work_status{job=\"day25-work-view\"}[$__range]))" }
],
"transformations": [
  { "id": "sortBy", "options": { "fields": {}, "sort": [ { "field": "impact" } ] } },
  { "id": "organize", "options": {
    "excludeByName": { "Time": true, "run": true, "Value": true },
    "indexByName": { "impact": 0, "likely_cause": 1, "first_check": 2, "confidence": 3, "generated_at": 4 },
    "renameByName": { "impact": "影響", "likely_cause": "AI 判斷，待確認", "first_check": "AI 建議先查", "confidence": "AI 自評把握", "generated_at": "產生時間" } } }
],
"fieldConfig": {
  "defaults": { "noValue": "沒有", "color": { "mode": "fixed", "fixedColor": "#8E7CC3" },
    "custom": { "align": "left", "cellOptions": { "type": "color-text", "wrapText": true } } },
  "overrides": [
    { "matcher": { "id": "byName", "options": "影響" }, "properties": [ { "id": "custom.width", "value": 200 } ] },
    { "matcher": { "id": "byName", "options": "AI 自評把握" }, "properties": [ { "id": "custom.width", "value": 110 } ] },
    { "matcher": { "id": "byName", "options": "產生時間" }, "properties": [ { "id": "custom.width", "value": 160 } ] }
  ]
},
"options": { "showHeader": true, "cellHeight": "sm" }

