        "transformations": [
          { "id": "organize", "options": {
            "excludeByName": { "Time": true, "run": true, "Value": true },
            "indexByName": { "question": 0, "answer": 1, "verified": 2, "first_step": 3, "generated_at": 4 },
            "renameByName": { "question": "問了什麼", "answer": "判斷", "verified": "用查詢驗證到什麼", "first_step": "先查哪裡", "generated_at": "產生時間" } } }
        ],
        "fieldConfig": {
          "defaults": { "noValue": "沒有", "color": { "mode": "fixed", "fixedColor": "#8E7CC3" },
            "custom": { "align": "left", "cellOptions": { "type": "color-text", "wrapText": true } } },
          "overrides": [
            { "matcher": { "id": "byName", "options": "問了什麼" }, "properties": [ { "id": "custom.width", "value": 200 } ] },
            { "matcher": { "id": "byName", "options": "產生時間" }, "properties": [ { "id": "custom.width", "value": 160 } ] }
          ]
        },'''.split('\n')
s[304:322]=new
open('dashboard.json','w',encoding='utf-8').write('\n'.join(s))
import json;json.load(open('dashboard.json',encoding='utf-8'))
EOF

